                      "path": "src/components/ui/alert/action.marko",
                      "content": "import { cn } from \"../../../lib/utils.ts\";\n\nexport interface Input extends Marko.Input<\"div\"> {}\n\n<const/{ class: className, content, ...rest }=input/>\n\n<div data-slot=\"alert-action\" class=cn(\"mu-alert-action\", className) ...rest>\n  <${content}/>\n</div>\n"
